cells={(0,1),(0,2),(0,4),(0,5)}|{(1,c) for c in range(6)}|{(2,1),(2,2),(2,4)}|{(3,2),(3,3),(3,4)}
# tile all using square and L tromino, exact covers
pieces=[]
for r in range(3):
 for c in range(5):
  p={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if p<=cells: pieces.append(('sq',p))
# Ls any 3 of 2x2
for r in range(3):
 for c in range(5):
  box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for omit in box:
   p=box-{omit}
   if p<=cells: pieces.append(('L',p))
sol=[]
def rec(rem,chosen):
 if not rem: sol.append(chosen); return
 x=min(rem)
 for typ,p in pieces:
  if x in p and p<=rem: rec(rem-p,chosen+[(typ,p)])
rec(cells,[])
len(sol)
